  ('TL3-07',130,'Technical Competence','3. Demonstrate efficient and safe rescue skills from a single sea kayak',' A self-rescue from a capsized kayak without the use of specialised equipment. Re-entry of kayak and ready to paddle within 2 minutes E.g.: re- entry and roll, ‘John Wayne’',true,true,true,true,false,false),
  ('TL3-07',140,'Technical Competence','3. Demonstrate efficient and safe rescue skills from a single sea kayak',' A self-rescue from a capsized kayak with the use of specialised equipment. Re-entry of kayak and ready to paddle in 2 minutes. E.g.: paddle float, stirrup, sling',true,true,true,true,false,false),
  ('TL3-07',150,'Technical Competence','3. Demonstrate efficient and safe rescue skills from a single sea kayak',' Competently and safely return student from capsize to a single kayak to be ready to paddle within 2 minutes',true,true,true,true,false,false),
