  ('CL2-10',150,'Internal Competency',null,'Check the engine and boat • Correct fuel mix, clean fuel • Engine Oil • Engine Mounts • Propeller play • Pontoon leaks • Hull integrity',false,false,false,true,false,false),
  ('CL2-10',160,'Internal Competency',null,'Identifies and has a strategy for all of: • Breakdown, prop loss, tell tale not functioning, water in fuel, fouled plugs, battery flat, punctured pontoon',false,false,false,true,false,false),
  ('CL2-10',170,'Internal Competency',null,'Weather, Sea State Awareness -Interpret weather map/forecast, and relate it to the local area. Make informed decisions on the local sea state and appropriateness for operations.',false,false,false,true,false,false),
  ('CL2-10',180,'Internal Competency',null,'Instructor identifies: • Effect of wind against tide • Effect of headlands and valleys • Local effects in Port Charles, Stony Bay and Waikawau bay • How weather conditions affect client’s learning progression',false,false,false,true,false,false),
